import assert from 'node:assert/strict';
import { spawn, execFileSync } from 'node:child_process';
import { mkdir, writeFile, readFile, open } from 'node:fs/promises';
import path from 'node:path';
import net from 'node:net';
import { NectarService } from '../../dist/service.js';
import { portOpen } from '../../dist/ports.js';
import { pidAlive } from '../../dist/commands.js';
import { serveEntries, serveStatus } from '../../dist/tailscale.js';
import { classifyServeEntry } from '../../dist/doctor.js';

const root = path.resolve(process.argv[2] ?? `.audit/demand-${Date.now()}`);
await mkdir(root, { recursive: true });
const repo = path.join(root, 'fixture');
await mkdir(repo);
const git = (...args) => execFileSync('git', args, { cwd: repo, stdio: 'pipe' });
git('init', '-b', 'main');
git('config', 'user.email', 'fixture@example.invalid');
git('config', 'user.name', 'Nectar fixture');
await writeFile(path.join(repo, 'nectar.toml'), 'name = "demand"\n[web]\nserve = "exec node server.mjs"\nready_timeout = "5s"\n');
await writeFile(path.join(repo, 'server.mjs'), 'import http from "node:http"; http.createServer((req,res)=>res.end("awake:"+process.env.NECTAR_ENV+":"+process.pid)).listen(Number(process.env.PORT),"127.0.0.1");\n');
git('add', '.');
git('commit', '-m', 'Fixture');
const state = path.join(root, 'state');
process.env.NECTAR_HOME = state;
process.env.NECTAR_SOCKET = path.join(root, 'control.sock');
const service = new NectarService(state);
await service.store.init();
const config = await service.store.readConfig();
await service.store.writeConfig({ ...config, upstream_port_start: 24100, upstream_port_end: 24299, tailnet_port_start: 19443, tailnet_port_end: 19542, pack_server_port: 24099, idle_stop_ms: 3000 });
const daemonLog = await open(path.join(root, 'daemon.log'), 'a');
let daemon = spawn(process.execPath, ['dist/cli.js', 'daemon', 'run', '--interval', '1s', '--gc-interval', '1h'], { env: process.env, stdio: ['ignore', daemonLog.fd, daemonLog.fd] });
const wait = ms => new Promise(resolve => setTimeout(resolve, ms));
const until = async (fn, ms = 15000) => { const end = Date.now() + ms; while (!(await fn())) { assert(Date.now() < end, 'timed out'); await wait(100); } };
const say = value => console.log(JSON.stringify(value));
try {
  await until(async () => { try { return Number(await readFile(path.join(state, 'nectard.pid'), 'utf8')) === daemon.pid; } catch { return false; } });
  for (let i = 1; i <= 16; i++) {
    const branch = `p${String(i).padStart(2, '0')}`;
    git('branch', branch);
    const result = await service.publish({ repo, branch, mode: 'web', local: true });
    const published = await service.store.readEnv(result.env);
    say({ publish: result.env, status: published.status, url: published.urls.mesh ?? published.urls.local });
  }
  const sleeping = await service.store.listEnvs();
  assert.equal(sleeping.length, 16);
  assert(sleeping.every(r => r.status === 'warm' && r.serve.pid === 0 && r.serve.upstream_port === undefined));
  say({ registered: sleeping.length, runningBeforeVisit: 0 });
  const active = [];
  for (const r of sleeping) {
    const started = performance.now();
    const url = r.urls.mesh ?? r.urls.local;
    const result = execFileSync('curl', ['--fail', '--silent', '--show-error', '--max-time', '15', url], { encoding: 'utf8' });
    assert(result.startsWith(`awake:${r.name}:`));
    const now = await service.store.readEnv(r.name);
    active.push({ name: r.name, pid: now.serve.pid, port: now.serve.upstream_port });
    say({ visit: url, coldWakeMs: Math.round(performance.now() - started), body: result });
  }
  await until(async () => (await service.store.listEnvs()).every(r => r.status === 'warm'), 20000);
  for (const r of active) { assert.equal(pidAlive(r.pid), false); assert.equal(await portOpen(r.port), false); }
  say({ idleWindowMs: 3000, stopped: active.length, pidsGone: true, upstreamPortsFreed: true });
  daemon.kill('SIGTERM');
  await new Promise(resolve => daemon.once('exit', resolve));
  daemon = spawn(process.execPath, ['dist/cli.js', 'daemon', 'run', '--interval', '1s', '--gc-interval', '1h'], { env: process.env, stdio: ['ignore', daemonLog.fd, daemonLog.fd] });
  await until(async () => { try { return Number(await readFile(path.join(state, 'nectard.pid'), 'utf8')) === daemon.pid; } catch { return false; } });
  await until(async () => (await Promise.all(sleeping.map(r => portOpen(r.serve.proxy_port)))).every(Boolean));
  assert((await service.store.listEnvs()).every(r => r.serve.pid === 0));
  say({ daemonRestart: true, appsRemainAsleep: 16, urlsUnchanged: true });
  const broken = sleeping[1];
  const app = path.join(broken.worktree, 'server.mjs');
  const original = await readFile(app, 'utf8');
  await writeFile(app, 'process.exit(1);');
  const failed = await fetch(broken.urls.local);
  assert.equal(failed.status, 503);
  const retryable = await service.store.readEnv(broken.name);
  assert.equal(retryable.status, 'warm');
  assert.equal(retryable.serve.pid, 0);
  assert.equal(retryable.serve.upstream_port, undefined);
  await writeFile(app, original);
  const recovered = await fetch(broken.urls.local);
  assert.equal(recovered.status, 200);
  await recovered.text();
  say({ failedWake: 503, remainsRetryable: true, subsequentVisit: 200 });
  const reset = sleeping[2];
  const resetApp = path.join(reset.worktree, 'server.mjs');
  const resetOriginal = await readFile(resetApp, 'utf8');
  await writeFile(resetApp, resetOriginal.replace('http.createServer(', 'setTimeout(() => http.createServer(').replace('"127.0.0.1");', '"127.0.0.1"), 500);'));
  const socket = net.connect(Number(new URL(reset.urls.local).port), '127.0.0.1');
  socket.on('error', () => undefined);
  await new Promise(resolve => socket.once('connect', resolve));
  socket.write('GET /ws HTTP/1.1\r\nHost: localhost\r\nConnection: Upgrade\r\nUpgrade: websocket\r\nSec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\nSec-WebSocket-Version: 13\r\n\r\n');
  await wait(50);
  socket.destroy();
  await wait(700);
  assert(pidAlive(daemon.pid));
  assert.equal((await fetch(reset.urls.local)).status, 200);
  say({ coldUpgradeClientReset: true, daemonSurvived: true });
  const r = sleeping[0];
  const again = execFileSync('curl', ['--fail', '--silent', '--show-error', '--max-time', '15', r.urls.mesh ?? r.urls.local], { encoding: 'utf8' });
  assert(again.startsWith(`awake:${r.name}:`));
  say({ tailnetRevisitAfterIdle: true, body: again });
  await until(async () => (await service.store.readEnv(r.name)).status === 'warm');
  const concurrencyStarted = performance.now();
  const replies = await Promise.all(Array.from({ length: 12 }, async () => { const response = await fetch(r.urls.local); assert.equal(response.status, 200); return response.text(); }));
  assert.equal(new Set(replies).size, 1);
  say({ revisit: r.urls.local, wakeMs: Math.round(performance.now() - concurrencyStarted), concurrentRequests: replies.length, sameProcess: true, body: replies[0] });
  await until(async () => (await service.store.readEnv(r.name)).status === 'warm');
  const finalVisit = execFileSync('curl', ['--fail', '--silent', '--show-error', '--max-time', '15', r.urls.mesh ?? r.urls.local], { encoding: 'utf8' });
  assert(finalVisit.startsWith(`awake:${r.name}:`));
  say({ secondTailnetRevisitAfterIdle: true, body: finalVisit });
  git('checkout', r.branch);
  await writeFile(path.join(repo, 'nectar.toml'), 'name = "demand"\n[web]\nserve = "exec node server.mjs"\nready_timeout = "5s"\n');
  git('add', '.');
  await writeFile(path.join(repo, 'package.json'), JSON.stringify({ name: 'demand-fixture', version: '0.0.0', private: true, scripts: { postinstall: 'sleep 1' } }));
  git('add', 'package.json');
  await writeFile(path.join(repo, 'version.txt'), 'republished\n');
  git('add', 'version.txt');
  git('commit', '-m', 'Republish fixture');
  const statuses = [];
  const latencies = [];
  let traffic = true;
  const driving = (async () => { while (traffic) { try { const requestStarted = performance.now(); const response = await fetch(r.urls.local); statuses.push(response.status); await response.text(); latencies.push(Math.round(performance.now() - requestStarted)); } catch { statuses.push(0); } await wait(20); } })();
  await service.publish({ repo, branch: r.branch, mode: 'web', local: true });
  await wait(300);
  traffic = false;
  await driving;
  assert(statuses.length > 10);
  assert(statuses.every(status => status === 200), JSON.stringify(statuses));
  say({ republishUnderTraffic: true, requests: statuses.length, non2xx: statuses.filter(status => status !== 200).length, maxLatencyMs: Math.max(...latencies), all200: true });
  await until(async () => (await service.store.listEnvs()).every(r => r.status === 'warm'));
  daemon.kill('SIGTERM');
  await new Promise(resolve => daemon.once('exit', resolve));
  await service.gc();
  const ports = new Set(sleeping.map(r => r.serve.tailnet_port));
  const retained = serveEntries(await serveStatus()).filter(entry => ports.has(entry.tailnetPort));
  assert.equal(retained.length, 16);
  const warmRecords = await service.store.listEnvs();
  assert(retained.every(entry => classifyServeEntry(entry, warmRecords, config, { answering: false, ownerAlive: false }).class === "owned"));
  say({ doctorClassifiesSleepingRoutesOwnedWithoutDaemon: true });
  say({ gcWithDaemonDown: true, sleepingTailnetRoutesRetained: retained.length });
  say({ PASS: true, root });
} finally {
  for (const r of await service.store.listEnvs()) {
    await until(async () => { try { await service.stop(r.name); return true; } catch (error) { if (error.code !== 'E_BUSY') throw error; return false; } });
  }
  if (daemon.exitCode === null && daemon.signalCode === null) {
    daemon.kill('SIGTERM');
    await new Promise(resolve => daemon.once('exit', resolve));
  }
  await daemonLog.close();
}
